<template>
  <div class="sf-premium-guide">
    <div v-if="!generalOverview" v-copy-block="{id:'entry-'+entryKind,fields:['category','next'].map(key=>'wall.entryStories.'+entryKind+'.'+key)}" class="sf-premium-guide__context"><sf-icon :name="wall.benefits[0].icon" :size="20"/><div><small :data-copy-key="'wall.entryStories.'+entryKind+'.category'">{{ wall.entry.category }}</small><strong>{{ wall.resource.name }}</strong><p :data-copy-key="'wall.entryStories.'+entryKind+'.next'">{{ wall.entry.next }}</p></div></div>
    <header v-copy-block="{id:'premium-intro',fields:['wall.education.title','wall.education.description']}" class="sf-premium-guide__intro"><span v-copy-block="{id:'paywall',fields:['paywall.guideEyebrow']}">{{ $copy('paywall.guideEyebrow') }}</span><h1>{{ wall.education.title }}</h1><p>{{ wall.education.description }}</p></header>
    <div class="sf-premium-guide__benefits">
    <div class="sf-premium-guide__tabs" role="tablist" aria-label="Premium benefits"><button v-for="item in wall.education.stories" :id="'premium-guide-tab-'+item.id" :key="item.id" v-copy-block="{id:'premium-'+item.id,fields:['wall.education.stories.'+storyIndex(item.id)+'.label']}" type="button" role="tab" :aria-selected="item.id===expanded?'true':'false'" :aria-controls="'premium-guide-detail-'+item.id" :tabindex="item.id===expanded?0:-1" :disabled="disabled" @click="select(item.id)" @keydown="navigate($event,item.id)"><span>{{ item.label }}</span></button></div>
    <section class="sf-premium-guide__stories" aria-label="How you can use Premium" @touchstart.passive="startSwipe" @touchend.passive="endSwipe">
      <article v-for="(item,index) in wall.education.stories" v-show="item.id===expanded" :id="'premium-guide-detail-'+item.id" :key="item.id" v-copy-block="{id:'premium-'+item.id,fields:storyFields(index)}" :data-benefit="item.id" class="is-expanded" role="tabpanel" :aria-labelledby="'premium-guide-tab-'+item.id">
        <h2>{{ item.title }}</h2><p>{{ item.description }}</p>
        <div v-if="item.id==='workouts'" class="sf-premium-guide__training"><sf-paywall-artwork kind="training"/><ul><li v-for="example in item.examples" :key="example"><sf-icon name="check" :size="15"/>{{ example }}</li></ul></div>
        <div v-else-if="item.id==='plans'" v-copy-block="{id:'paywall',fields:['paywall.planExampleLabel','paywall.planExample1','paywall.planExample2','paywall.planExample3']}" class="sf-premium-guide__example sf-premium-guide__week"><small>{{ $copy('paywall.planExampleLabel') }}</small><div v-for="(day,i) in ['Mon','Wed','Fri']" :key="day"><span>{{ day }}</span><strong>{{ $copy('paywall.planExample'+(i+1)) }}</strong><span>15 min</span></div></div>
        <div v-else-if="item.id==='insights'" v-copy-block="{id:'paywall',fields:['paywall.insightExampleLabel','paywall.insightExampleBody']}" class="sf-premium-guide__example"><small>{{ $copy('paywall.insightExampleLabel') }}</small><div class="sf-premium-guide__metrics"><span><strong>40:23</strong>Duration</span><span><strong>4 / 10</strong>Effort</span></div><p>{{ $copy('paywall.insightExampleBody') }}</p></div>
        <div v-else v-copy-block="{id:'paywall',fields:['paywall.exampleLabel','paywall.exampleQuestion','paywall.exampleAnswer']}" class="sf-premium-guide__example sf-premium-guide__conversation"><small>{{ $copy('paywall.exampleLabel') }}</small><p>{{ $copy('paywall.exampleQuestion') }}</p><p><sf-icon name="coach" :size="18"/>{{ $copy('paywall.exampleAnswer') }}</p></div>
        <ul v-if="item.id!=='workouts'" class="sf-premium-guide__included"><li v-for="example in item.examples" :key="example"><sf-icon name="check" :size="15"/>{{ example }}</li></ul><p class="sf-premium-guide__detail">{{ item.detail }}</p>
      </article>
    </section>
    </div>
    <section class="sf-premium-guide__comparison" aria-label="Free and Premium comparison"><h2 v-copy-block="{id:'paywall',fields:['paywall.comparisonTitle']}">{{ $copy('paywall.comparisonTitle') }}</h2><table v-copy-block="{id:'premium-intro',fields:comparisonFields}"><thead><tr><th scope="col">Included</th><th scope="col">Free</th><th scope="col">Premium</th></tr></thead><tbody><tr v-for="row in wall.education.comparison" :key="row[0]"><th scope="row">{{ row[0] }}</th><td>{{ row[1] }}</td><td>{{ row[2] }}</td></tr></tbody></table><p v-copy-block="{id:'paywall',fields:['paywall.separateBilling']}" class="sf-premium-guide__boundary">{{ $copy('paywall.separateBilling') }}</p></section>
    <details class="sf-premium-guide__questions" aria-label="Common questions"><summary v-copy-block="{id:'paywall',fields:['paywall.faqTitle']}">{{ $copy('paywall.faqTitle') }}<sf-icon name="plus" :size="16"/></summary><div v-copy-block="'premium-faq'"><details v-for="question in questions" :key="question.title"><summary>{{ question.title }}<sf-icon name="plus" :size="16"/></summary><p>{{ question.answer }}</p></details></div></details>
