  </div>
</template>
<script>
import SfIcon from './SfIcon'
import SfPaywallArtwork from './SfPaywallArtwork'
import wallStructure from '../../../config/subscription-wall.structure.json'
export default {
  components:{SfIcon,SfPaywallArtwork},props:{wall:{type:Object,required:true},benefitId:String,disabled:Boolean,disclosure:String,trial:Boolean},
  data(){return {expanded:this.benefitId||this.wall.entry.defaultBenefit,swipeStart:null}},
  computed:{entryKind(){return Object.keys(wallStructure.placements).find(kind=>wallStructure.placements[kind].placementId===this.wall.placementId)},generalOverview(){return this.wall.placementId==='membership.explore'},questions(){return this.wall.education.questions},comparisonFields(){return this.wall.education.comparison.flatMap((row,i)=>row.map((_,j)=>'wall.education.comparison.'+i+'.'+j))}},
  watch:{benefitId(id){if(this.wall.education.stories.some(item=>item.id===id))this.expanded=id}},
  methods:{select(id){if(this.disabled)return;this.expanded=id;this.$emit('benefit',id)},startSwipe(event){const touch=event.changedTouches[0];this.swipeStart=touch?{x:touch.clientX,y:touch.clientY}:null},endSwipe(event){const start=this.swipeStart,touch=event.changedTouches[0];this.swipeStart=null;if(!start||!touch||this.disabled||window.getSelection()?.toString())return;const dx=touch.clientX-start.x,dy=touch.clientY-start.y;if(Math.abs(dx)<60||Math.abs(dx)<Math.abs(dy)*1.5)return;const stories=this.wall.education.stories,index=this.storyIndex(this.expanded),next=Math.max(0,Math.min(stories.length-1,index+(dx<0?1:-1)));if(next!==index)this.select(stories[next].id)},storyIndex(id){return this.wall.education.stories.findIndex(item=>item.id===id)},navigate(event,id){const keys=['ArrowRight','ArrowLeft','ArrowDown','ArrowUp','Home','End'];if(!keys.includes(event.key))return;event.preventDefault();const stories=this.wall.education.stories,index=this.storyIndex(id),next=event.key==='Home'?0:event.key==='End'?stories.length-1:(index+(event.key==='ArrowRight'||event.key==='ArrowDown'?1:-1)+stories.length)%stories.length;this.select(stories[next].id);this.$nextTick(()=>this.$el.querySelector('#premium-guide-tab-'+stories[next].id)?.focus({preventScroll:true}))},storyFields(index){const base='wall.education.stories.'+index+'.';return ['label','title','description','detail',...this.wall.education.stories[index].examples.map((_,i)=>'examples.'+i)].map(key=>base+key)}}
}
</script>
